import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    static class Solver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int l = in.nextInt() - 1;
            int r = in.nextInt() - 1;
            int period = a + b;
            int blocks = 4;
            int[] cc = new int[period * blocks];

            int shift = l / period;
            l -= shift * period;
            r -= shift * period;
            shift = (r - l + 1) / period;
            if (shift > 2) {
                r -= (shift - 2) * period;
            }

            int d = a > b ? a - b : 1;

            for (shift = 0; shift < blocks; shift++) {
                for (int k = 0; k < a - d; k++) {
                    cc[period * shift + k] = k;
                }
                for (int k = 0; k < d; k++) {
                    cc[period * shift + a - d + k] = shift % 2 == 0 ? a - d + k : a + k;
                }
            }

            int min = a + a;
            long d2 = (long) d * d;
            long d3 = d2 * d;
            long total = d3 * d;

            for (long idx = 0; idx < total; idx++) {
                int k0 = (int) (idx / d3) + 1;
                long rem = idx % d3;
                int k1 = (int) (rem / d2) + 1;
                rem %= d2;
                int k2 = (int) (rem / d) + 1;
                int k3 = (int) (rem % d) + 1;

                for (int k = 0; k < b; k++) {
                    cc[period * 0 + a + k] = cc[period * 0 + a - k0];
                }
                for (int k = 0; k < b; k++) {
                    cc[period * 1 + a + k] = cc[period * 1 + a - k1];
                }
                for (int k = 0; k < b; k++) {
                    cc[period * 2 + a + k] = cc[period * 2 + a - k2];
                }
                for (int k = 0; k < b; k++) {
                    cc[period * 3 + a + k] = cc[period * 3 + a - k3];
                }

                min = Math.min(min, count(cc, l, r));
            }

            out.println(min);
        }

        static int count(int[] cc, int l, int r) {
            boolean[] used = new boolean[24];
            int cnt = 0;
            for (int i = l; i <= r; i++) {
                int c = cc[i];
                if (!used[c]) {
                    used[c] = true;
                    cnt++;
                }
            }
            return cnt;
        }
    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int charsRead;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (charsRead == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= charsRead) {
                curChar = 0;
                try {
                    charsRead = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (charsRead <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
